import random
from collections import defaultdict

def check_girth(edges_set, n):
    """Check if graph has girth >= 6"""
    # Build adjacency list
    adj = [set() for _ in range(n)]
    for u, v in edges_set:
        adj[u].add(v)
        adj[v].add(u)

    # Check for cycles of length 3, 4, 5 using BFS from each vertex
    for start in range(n):
        # BFS
        dist = {start: 0}
        parent = {start: None}
        queue = [start]

        for v in queue:
            for w in adj[v]:
                if w not in dist:
                    dist[w] = dist[v] + 1
                    parent[w] = v
                    queue.append(w)
                elif parent[v] != w and dist[w] >= dist[v]:
                    # Found a cycle
                    cycle_len = dist[v] + dist[w] + 1
                    if cycle_len < 6:
                        return False

    return True

def try_random_construction(n=21, max_attempts=10000):
    for attempt in range(max_attempts):
        edges = set()
        degrees = [0] * n

        # Try to add edges randomly
        possible_edges = [(i, j) for i in range(n) for j in range(i+1, n)]
        random.shuffle(possible_edges)

        for u, v in possible_edges:
            if degrees[u] >= 5 or degrees[v] >= 5:
                continue

            # Check if adding this edge creates a short cycle
            # Quick check: if u and v have a common neighbor, adding edge creates triangle
            # We need to track adjacency

            # Let's just try adding and check later
            edges.add((u, v))
            degrees[u] += 1
            degrees[v] += 1

        # Check if all degrees are at least 3
        if all(3 <= d <= 5 for d in degrees):
            if check_girth(edges, n):
                return edges, degrees

        if attempt % 1000 == 0:
            print(f"Attempt {attempt}, degrees: {sorted(degrees)}")

    return None, None

